package kr.releasepilot.controlplane.rollout;
import kr.releasepilot.controlplane.connection.*;import kr.releasepilot.controlplane.environment.*;import kr.releasepilot.controlplane.release.*;import kr.releasepilot.controlplane.notification.GithubCheckService;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class RolloutStateReconciler{
 private final RolloutExecutionRepository executions;private final ReleaseRepository releases;private final ReleaseArtifactRepository artifacts;private final EnvironmentRepository environments;private final ClusterConnectionRepository clusters;private final SecretResolver secrets;private final ArgoRolloutsGateway argo;private final Clock clock;private final GithubCheckService githubChecks;private final RolloutStepRepository steps;
 public RolloutStateReconciler(RolloutExecutionRepository executions,ReleaseRepository releases,ReleaseArtifactRepository artifacts,EnvironmentRepository environments,ClusterConnectionRepository clusters,SecretResolver secrets,ArgoRolloutsGateway argo,Clock clock,GithubCheckService githubChecks,RolloutStepRepository steps){this.executions=executions;this.releases=releases;this.artifacts=artifacts;this.environments=environments;this.clusters=clusters;this.secrets=secrets;this.argo=argo;this.clock=clock;this.githubChecks=githubChecks;this.steps=steps;}
 @Transactional public int reconcileActive(){int count=0;for(var execution:executions.findByStatusIn(List.of(RolloutExecutionStatus.RUNNING,RolloutExecutionStatus.PAUSED))){reconcile(execution);count++;}return count;}
 private void reconcile(RolloutExecution execution){var release=releases.findById(execution.getReleaseId()).orElseThrow();var env=environments.findById(release.getEnvironmentId()).orElseThrow();var cluster=clusters.findById(execution.getClusterId()).orElseThrow();var token=secrets.resolve(cluster.getSecretRef()).orElseThrow(()->new IllegalStateException("Cluster secret is unavailable"));var observation=argo.observe(new ArgoRolloutsGateway.ObserveRequest(cluster.getApiServer(),token.bearerToken(),execution.getNamespace(),execution.getRolloutName(),env.getContainerName()));if(!Objects.equals(execution.getRolloutUid(),observation.uid())){execution.failed(clock.instant());release.failed(clock.instant());githubChecks.completed(release.getId(),release.getVersion(),false,"rollout identity changed");return;}var artifact=artifacts.findByReleaseId(release.getId()).orElseThrow();String expected=artifact.getImageRepository()+"@"+artifact.getImageDigest();if(!expected.equals(observation.image())){execution.failed(clock.instant());release.failed(clock.instant());githubChecks.completed(release.getId(),release.getVersion(),false,"deployed image mismatch");return;}execution.observed(observation.resourceVersion(),observation.currentStepIndex());if(!observation.controllerObservedDesiredGeneration())return;if("Healthy".equalsIgnoreCase(observation.phase())){var policySteps=steps.findByExecutionIdOrderByStepIndexAsc(execution.getId());if(policySteps.isEmpty()||policySteps.stream().anyMatch(step->step.getStatus()!=RolloutStepStatus.PASSED))return;var now=clock.instant();execution.succeeded(now);release.succeeded(now);githubChecks.completed(release.getId(),release.getVersion(),true,"succeeded");}else if("Degraded".equalsIgnoreCase(observation.phase())&&!observation.aborted()){var now=clock.instant();execution.failed(now);release.failed(now);githubChecks.completed(release.getId(),release.getVersion(),false,"rollout degraded");}}
}
